def _test_case_at(where):
    """Return the literal Snow case containing a source line, or None."""
    source, separator, line = where.rpartition(":")
    if not separator or not line.isdigit():
        return None
    source = source.replace("\\", "/")
    if not os.path.isfile(source):
        # Valgrind commonly reports just the basename of a debug source file.
        source = os.path.join("tests", "unit", os.path.basename(source))
    try:
        with open(source, encoding="utf-8", errors="replace") as handle:
            text = handle.read()
    except OSError:
        return None
    offsets = [0]
    offsets.extend(match.end() for match in re.finditer("\n", text))
    lineno = int(line)
    if lineno < 1 or lineno > len(offsets):
        return None
    position = offsets[lineno - 1]
    # Ignore braces in strings, characters, and comments while finding each body.
    tokens = re.compile(
        r'/\*.*?\*/|//[^\n]*|"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\'|[{}]', re.S
    )
    for case in re.finditer(
        r'\b(?:it|test)\s*\(\s*"((?:\\.|[^"\\])*)"\s*\)\s*\{', text
    ):
        start = case.end() - 1
        depth = 0
        for token in tokens.finditer(text, start):
            if token.group() == "{":
                depth += 1
            elif token.group() == "}":
                depth -= 1
                if depth == 0:
                    if start <= position <= token.end():
                        return case.group(1)
                    break
    return None


