# Prompt: "Separate test diagnostics from stderr and identify leak allocation origins."
# Changes: Report every loss record with its test allocation origin or source frame.
def _leak_origins(log):
    records = list(LOSS_RECORD_RE.finditer(log))
    origins = []
    for index, record in enumerate(records):
        end = records[index + 1].start() if index + 1 < len(records) else len(log)
        block = log[record.start() : end]
        origin = None
        for frame in FRAME_RE.finditer(block):
            where = frame.group(2).strip()
            case = _test_case_at(where)
            if case is not None:
                origin = f'allocation in test "{case}" @ {where}'
                break
        if origin is None:
            site = _leak_site(block)
            origin = (
                f"allocation @ {site}" if site else "test allocation origin unavailable"
            )
        # Include the record number, which appears after the matched heading.
        heading = log[record.start() :].splitlines()[0]
        heading = re.sub(r"^==\d+==\s*", "", heading).strip()
        origins.append(f"{heading}: {origin}")
    return origins


BUILD_DIR = os.path.join("build", platform.system().lower(), "tests")


def discover_binaries(build_dir):
    names = []
    for entry in sorted(os.listdir(build_dir)):
        if not entry.startswith("test_"):
            continue
        path = os.path.join(build_dir, entry)
        if not os.path.isfile(path):
            continue
        if entry.endswith(".exe"):
            # Windows test binary.
            names.append(path)
        elif "." not in entry and os.access(path, os.X_OK):
            # POSIX test binary (extensionless executable).
            names.append(path)
    return names


